/**
 * Auth Service - Handles all authentication-related API calls
 * 
 * Responsibilities:
 * - Sign up, sign in, sign out
 * - Token management
 * - User profile operations
 * 
 * Import rules:
 * - Can import: apiClient
 * - Should NOT import: components, hooks, context (to avoid circular deps)
 */

import apiClient from './apiClient';

export const authService = {
  /**
   * Sign up a new user
   * POST /api/auth/signup
   */
  signup: async (email, password, name) => {
    return apiClient.post('/auth/signup', { email, password, name });
  },

  /**
   * Sign in existing user
   * POST /api/auth/signin
   */
  signin: async (email, password) => {
    return apiClient.post('/auth/signin', { email, password });
  },

  /**
   * Sign out current user
   * POST /api/auth/signout
   */
  signout: async () => {
    return apiClient.post('/auth/signout');
  },

  /**
   * Get current user profile
   * GET /api/users/me
   */
  getCurrentUser: async () => {
    return apiClient.get('/users/me');
  },
};
